// Phase 15: the sound bank — SDL3 audio with graceful degradation.
//
// Samples are 16-bit mono 44100 Hz PCM WAVs generated by
// tools/generate_sounds.py into assets/sounds/. init() loads every *.wav
// in the asset directory (sorted by file name, deterministic), opens the
// default playback device through an SDL audio stream, and scales
// playback by the configured volume (config audio.volume).
//
// Graceful degradation: when the audio subsystem or the device cannot be
// opened (headless machine, no sound server), init() logs a warning and
// the bank is DISABLED — every play() is a no-op and the game runs
// exactly as before. A malformed individual file is skipped with a
// warning; play() of an unknown name is a silent no-op.
//
// parseWav / applyGain are pure (no SDL) and unit-tested.
#pragma once

#include <cstdint>
#include <string>
#include <unordered_map>
#include <vector>

#include "core/asset_manager.hpp"
#include "core/error.hpp"

struct SDL_AudioStream;

namespace mc {

struct WavSample {
    std::vector<std::int16_t> pcm;
    int rate = 44100;
};

class SoundBank {
public:
    SoundBank() = default;
    ~SoundBank();
    SoundBank(const SoundBank&) = delete;
    SoundBank& operator=(const SoundBank&) = delete;

    // Opens the audio device and loads assets/<dir>/*.wav. Never fails:
    // on any audio problem the bank stays disabled (enabled() == false).
    void init(AssetManager& assets, const std::string& dir, float volume);
    // Closes the stream/device and drops the samples. Idempotent.
    void shutdown();

    bool enabled() const { return m_enabled; }
    std::size_t sampleCount() const { return m_samples.size(); }
    // Queues the named sample (scaled by the volume). No-op when the bank
    // is disabled or the name is unknown.
    void play(const std::string& name);

    // Pure helpers (unit-tested without SDL).
    // Strict 16-bit mono PCM reader: skips unknown chunks, rejects
    // non-RIFF/WAVE data, non-PCM formats, other channel/bit counts and
    // any rate other than 44100 Hz (all generated sounds share the rate,
    // so the stream input format is fixed once).
    static Result<WavSample> parseWav(const std::vector<std::uint8_t>& data);
    // Scales the samples by gain, clamping to the 16-bit range.
    static std::vector<std::int16_t> applyGain(
        const std::vector<std::int16_t>& pcm, float gain);

private:
    // The device is owned by the stream (SDL_DestroyAudioStream closes it).
    SDL_AudioStream* m_stream = nullptr;
    bool m_ownsAudioSubSystem = false;
    float m_volume = 1.0f;
    std::unordered_map<std::string, WavSample> m_samples;
    bool m_enabled = false;
};

} // namespace mc
